pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(string calldata description, address team) public {
        vm.assume(team != address(0));
        // Set jojoTeam to a fuzzed address
        vm.store(address(c), bytes32(uint256(0)), bytes32(uint256(uint160(team))));
        vm.startPrank(team);

        // Record logs before
        uint256 preLogs = vm.getRecordedLogs().length;

        // call newEmergencyOracle with fuzzed description
        c.newEmergencyOracle(description);

        vm.stopPrank();

        // Record logs after
        Vm.Log[] memory logs = vm.getRecordedLogs();
        uint256 postLogs = logs.length;

        // There should be exactly one new log (the NewEmergencyOracle event)
        bool eventEmitted = (postLogs == preLogs + 1);

        // If event was emitted, verify its topics match NewEmergencyOracle
        if (eventEmitted) {
            Vm.Log memory lastLog = logs[postLogs - 1];
            // Topic0 is keccak256("NewEmergencyOracle(address,address)")
            bytes32 expectedTopic0 = keccak256("NewEmergencyOracle(address,address)");
            assertTrue(lastLog.topics[0] == expectedTopic0, "Event topic mismatch");
        } else {
            assertTrue(false, "NewEmergencyOracle event was not emitted");
        }
    }
}

